package com.simplysync.kotlin

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test

/**
 * Cross-language crypto conformance: the Kotlin port must derive the same
 * identity and produce byte-identical envelopes as the TS protocol
 * (@simplysync/protocol) and the Swift port. Driven by the shared corpus
 * `vectors.json` (generated by the TS protocol — see
 * packages/simplysync-protocol/scripts/gen-vectors.ts; the copy under
 * src/test/resources is byte-identical). Plan 001; the mnemonic entry also
 * guards the PROTO-01 reconciliation (Kotlin now uses the "SimplySync"
 * SLIP-21 paths, so a mnemonic resolves to the same ownerId everywhere).
 */
class ConformanceTest {
    // Fixed generator inputs shared across all languages (see the Swift
    // verify/main.swift harness and gen-vectors.ts).
    private val eventId = "00000abcde-0000-dev1"
    private val deviceId = "dev1"
    private val createdAt = "2026-01-01T00:00:00.000Z"

    private fun fixedPayload() = SyncPayload(
        schemaVersion = 1,
        table = "todo",
        op = "upsert",
        rowId = "row-123",
        hlc = "00000abcde-0000-dev1",
        value = linkedMapOf(
            "done" to JsonValue.IntVal(0),
            "title" to JsonValue.Str("Hello from JS"),
        ),
    )

    private fun corpus(): Map<String, kotlinx.serialization.json.JsonElement> {
        val url = javaClass.getResource("/vectors.json")
        assertNotNull("vectors.json must be on the test classpath", url)
        return Json.parseToJsonElement(url!!.readText()).jsonObject
    }

    @Test
    fun matchesSharedCrossLanguageCorpus() {
        val entries = corpus()
        // Both a native sf1_ recovery key and a BIP39 mnemonic must be covered.
        assertEquals(setOf("sf1", "mnemonic"), entries.keys)

        for ((name, elem) in entries) {
            val v = elem.jsonObject
            fun field(k: String) = v[k]!!.jsonPrimitive.content

            // derive() auto-detects sf1_ vs mnemonic, like the TS deriveIdentity.
            val identity = IdentityDeriver.derive(field("input"))
            assertEquals("$name ownerId", field("ownerId"), identity.ownerId)
            assertEquals("$name relayAuth", field("relayAuth"), identity.relayAuth)
            assertEquals(
                "$name streamKeyB64",
                field("streamKeyB64"),
                Base64Url.encode(identity.streamKey),
            )

            // Seal with the corpus's fixed nonce → exact streamId + ciphertext.
            val nonce = Base64Url.decode(field("nonceB64"))
            assertNotNull("$name nonce decodes", nonce)
            val env = Envelope.seal(
                identity, eventId, deviceId, createdAt, fixedPayload(), nonce!!,
            )
            assertEquals("$name streamId", field("streamId"), env.streamId)
            assertEquals("$name ciphertext", field("ciphertextB64"), env.ciphertext)

            // And the envelope round-trips back to the original payload.
            val decrypted = Envelope.decrypt(identity, env)
            assertEquals("$name table", "todo", decrypted.table)
            assertEquals(
                "$name value.title",
                JsonValue.Str("Hello from JS"),
                decrypted.value["title"],
            )
        }
    }
}
